&= \left\| (\mathbf{a} + \mathbf{b}) \cdot \left( \mathbf{b} \times \mathbf{c} + 3 \mathbf{b} \times \mathbf{a} + 3 \mathbf{c} \times \mathbf{c} - 3 \mathbf{c} \times 7 \mathbf{a} - 7 \mathbf{b} \times \mathbf{a} \right) \right\| \\
